def solve(text):
    if not text or not text.strip():
        return None

    # Remove whitespace
    text = text.strip()

    # Check for valid suffix
    suffix = ''
    i = len(text) - 1
    while i >= 0 and text[i] in '0123456789':
        i -= 1
    if i < 0:
        return None

    # Extract the number part
    num_str = text[:i+1]
    if not num_str or not num_str.lstrip('-').lstrip('.'):
        return None

    # Extract suffix
    suffix = text[i+1:]

    # Validate suffix
    valid_suffixes = {'ms', 's', 'm', 'h'}
    if suffix not in valid_suffixes:
        return None

    # Parse the number
    try:
        num = int(num_str)
    except ValueError:
        return None

    # Convert to milliseconds
    if suffix == 'ms':
        return num
    elif suffix == 's':
        return num * 1000
    elif suffix == 'm':
        return num * 60000

